#!/usr/bin/env python3
"""Concise receipt from actual exported measurements; no runtime/profile data is read."""
import json
from pathlib import Path
E=Path('dashboard/evidence')
def read(name):return json.loads((E/name).read_text())
perf=read('owner-direct-performance.json')['trials'];coverage=read('owner-direct-coverage.json')['trials'];visual=read('owner-direct-visual-comparison.json');cal=read('owner-direct-cpu-units.json')['operationStatistics'];trace=read('owner-direct-attribution.json');manifest=read('owner-direct-source.json');meta=next(iter(perf.values()))['metadata']
lines=['Voxel Sandbox streaming revision: results and limits','',f'Implementation SHA256: {manifest["sourceSha256"]}',f'Feature JAR SHA256: {manifest["featureJarSha256"]}',f'Baseline JAR SHA256: {manifest["baselineJarSha256"]}','Baseline engine: review base403033b9f53ce66063982879c6e2daff684a427b with the reviewed timing overlay.','',f'Environment: {meta["os"]}/{meta["architecture"]}; Java {meta["javaVersion"]}; {meta["processors"]} JVM-visible processors; heap {meta["maxHeapBytes"]} bytes; {meta["renderer"]} SOFTWARE rendering; actual framebuffer {meta["width"]}x{meta["height"]}.','All six runs match renderer/JVM/heap/processor/framebuffer/graphics/route metadata. Seed 748291; same 810 preloaded chunks; readiness-based warm-up; 166 samples per fresh synthetic profile. Recording/JFR/host probes were OFF. Full settings: owner-direct-provenance.json.','Legacy *_cpu_ms and accountedStreamingCpuMs fields are elapsed owner stages, including waits. They are not thread CPU. Baseline mesh accounting includes snapshot/upload only and conservatively omits baseline scheduling. Percentiles use nearest rank.','','Cold-flight frames, ms (80 samples per row):','trial phase | p50 | p95 | p99 | worst | 1% low FPS | >33/50/100ms']
for i in range(1,4):
 for phase in ('before','after'):
  d=perf[f'owner-direct-{phase}-{i}']['segments']['coldFlight'];v=d['frame_ms'];lines.append(f'{i} {phase} | '+' | '.join(f'{v[k]:.3f}' for k in ('p50','p95','p99','worst'))+f' | {d["onePercentLowFps"]:.3f} | '+'/'.join(str(d['overMs'][str(n)]) for n in (33,50,100)))
lines+=['','Cold-flight accounted owner stages, ms:','trial | before p50/p95/p99 | after p50/p95/p99 | terrain-stream p99 before/after | nearby resident frames']
for i in range(1,4):
 b=perf[f'owner-direct-before-{i}']['segments']['coldFlight'];a=perf[f'owner-direct-after-{i}']['segments']['coldFlight'];fmt=lambda x:'/'.join(f'{x[k]:.3f}' for k in ('p50','p95','p99'));lines.append(f'{i} | {fmt(b["accountedStreamingCpuMs"])} | {fmt(a["accountedStreamingCpuMs"])} | {b["stream_cpu_ms"]["p99"]:.3f}/{a["stream_cpu_ms"]["p99"]:.3f} | {a["nearbyResidentFrames"]}/80')
lines+=['','Cold-flight frame p99 improved in every pair. Terrain-stream p99 fell 97.29–98.74%; accounted owner-stage p99 fell 95.23–97.84%. The 2ms elapsed tail target remains UNMET. Source allowances are 2ms steady and 4ms catch-up, with initial 8ms limited to 64 updates. A stage can contain several bounded units.','','All-route frame p99, before/after ms:']
for i in range(1,4):lines.append(f'{i}: {perf[f"owner-direct-before-{i}"]["all"]["frame_ms"]["p99"]:.3f}/{perf[f"owner-direct-after-{i}"]["all"]["frame_ms"]["p99"]:.3f}')
lines+=['Do not substitute cold-flight results for all-route performance. A feature resident outlier was 8775.427ms: 8630.114ms in render(), about 0.399ms in streaming stages, GC0 and GPU EMA7233ms. The EMA is not a per-frame GPU distribution; exact host/driver cause is unproven. This host does not sustain 60FPS, so the physical 60FPS frame targets remain unqualified. Full per-stage/segment/queue/byte/heap distributions and raw CSV/JSON are retained.','','Separate 166-sample JFR/host attribution:']
for operation in ('mesh.update','sky.update','gl.pixels3D','lighting.pump'):
 rows=[x for x in trace['overruns'] if x['operation']==operation];x=max(rows,key=lambda x:x['wallMs']);lines.append(f'{operation}: wall {x["wallMs"]:.3f}ms; thread CPU {x["threadCpuMs"]:.3f}ms; verified scheduler wait {x["verifiedSchedulerWaitMs"]:.3f}ms; GC overlap {x["verifiedGcPauseOverlapMs"]:.3f}ms; safepoint overlap {x["verifiedSafepointOverlapMs"]:.3f}ms.')
lines+=['Overlap categories are not independent durations and must not be added. These diagnostic examples do not retrospectively classify every separate normal-run tail. A 9.539ms sky diagnostic outlier sampled the optional OwnerTrace.throttle file read itself, disabled in normal runs. Residual time without verified evidence stays unclassified. Raw JFR remains private; all whitelisted events, operation rows and clock anchors are exported in sanitized form.','','64-sample calibration, host probes and JFR OFF; maximum thread CPU ms:']
for name in ('mesh.request','mesh.snapshot','mesh.allocate','mesh.upload','sky.capture','sky.validate','gi.capture','gi.update','gl.pixels3D','sky.update','mesh.update','render.prepare'):lines.append(f'{name}: {cal[name]["threadCpuMs"]["worst"]:.4f}')
lines+=['The 3.704ms render.prepare maximum is an aggregate catch-up stage. Pixel units are capped at 256KiB; maximum observed was 245760 bytes. Captures are sliced, queues bounded, and full GPU stores prepared at startup. A prior 1MiB glBufferSubData unit used up to 2.897ms CPU. Smaller mapped copies replace it; llvmpipe/softpipe uses direct client-memory transfers. Other renderers retain fenced mapped PBO. Both paths passed exact full-volume readback, cancellation, reuse and cleanup. No quality/distance/resolution/horizon/format reduction was used.','','Allocation regression, not an FPS test:']
b=read('owner-direct-terrain-before.json');a=read('owner-direct-terrain-after.json');lines.append(f'Terrain.block version3, seed748291, 1048576 warmed queries: allocation {b["allocatedBytes"]} -> {a["allocatedBytes"]} bytes; thread CPU {b["threadCpuNs"]} -> {a["threadCpuNs"]}ns. Exact digest remained {a["digest"]}. Primitive bounded LRU lookups remove boxed keys/capturing lambdas; refined-light lookup uses a direct cell index. Generator algorithms/versions are unchanged.')
lines+=['','Lighting readiness, coverage and age:']
for i in range(1,4):
 b=coverage[f'owner-direct-before-{i}'];a=coverage[f'owner-direct-after-{i}'];c=a['segments']['coldFlight'];lines.append(f'Trial {i}: canonical warm-up {b["warmup"]["warmupWallMs"]/1000:.3f}s -> {a["warmup"]["warmupWallMs"]/1000:.3f}s; current center {c["currentCenterCovered"]}/80; nine-point coverage {c["nineHorizontalCovered"]}/80 versus baseline55/80; current-field capture age p99 {c["sourceAgeMsCurrentCenter"]["p99"]}ms.')
lines+=['An unchanged field can be old; local geometry is validated separately from elapsed age.','Dense resolved-depth checks match all 80 cold-flight and 16 reversal eye poses. Near-surface coverage: 59.3705% -> 89.6160%; zero/longest-zero frames: 25 -> 6. Every matched frame has equal or higher coverage. Reversal is 100% in both. Six uncovered cold frames remain. Cold frame64 and reversal112 image pairs were inspected.','Ground-view visual warm-up was 78.131s baseline and 99.699s feature, including startup/resident preparation; this visual run is excluded from timing. Jump/teleport poses differ at six listed samples and are not matched visual qualification. Functional transitions are tested separately. Raw depth/coverage/images retain those differences.','','Media: actual F10 flight, 18.176s, 530593 bytes, 10 decoded images; midpoint inspected. Separate capture elapsed median142.264ms/worst202.984ms includes readback/waits; not thread CPU or net FPS penalty. No recording ran in the six profiling trials.','','Limits/handoff: the 2ms elapsed tail target, initial uncovered GI frames and physical Windows/GPU qualification remain open limits. Stable rollout stays gated on physical qualification. Windows steps: owner-direct-windows-playtest.txt. Final native travel/memory/soak/lifecycle results are in the validation receipt. Controller owns publication, CI, independent review and the existing client/launcher release pipeline.']
(E/'owner-direct-summary.txt').write_text('\n'.join(lines)+'\n')
print('Wrote measured summary. Final travel/soak validation remains pending.')
